scala
case class CacheTableCommand(
    table: TableIdentifier,
    storageLevel: Option[String] = None,
    lazyCache: Boolean = false)
  extends RunnableCommand {

  override def run(sparkSession: SparkSession): Seq[Row] = {
    val catalog = sparkSession.sessionState.catalog
    try {
      val tableMeta = catalog.getTableMetadata(table)
      val plan = sparkSession.sessionState.sqlParser.parsePlan(s"SELECT * FROM ${table.unquotedString}")
      val dataset = sparkSession.newSession().sql(plan.toString)

      val storageLevelObj = storageLevel match {
        case Some(level) => StorageLevel.fromString(level)
        case None => StorageLevel.MEMORY_ONLY
      }

      if (lazyCache) {
        dataset.cache()
      } else {
        dataset.persist(storageLevelObj)
      }

      // Register the cached table in the catalog
      catalog.cacheTable(table)
      Seq.empty[Row]
    } catch {
      case e: NoSuchTableException =>
        throw new IllegalArgumentException(s"Table ${table.unquotedString} does not exist.", e)
    }
  }
}

