scala
object CacheTableCommand {
  def apply(tableName: String, storageLevel: String): CacheTableCommand = {
    new CacheTableCommand(TableIdentifier(tableName), storageLevel)
  }

  def apply(tableName: String): CacheTableCommand = {
    new CacheTableCommand(TableIdentifier(tableName))
  }
}

case class CacheTableCommand(
    tableIdentifier: TableIdentifier,
    storageLevel: String = "MEMORY_ONLY")
  extends RunnableCommand {

  override def run(sparkSession: SparkSession): Seq[Row] = {
    val catalog = sparkSession.sessionState.catalog
    val table = catalog.getTableMetadata(tableIdentifier)

    // Check if the table is already cached
    if (sparkSession.catalog.isCached(table.identifier.table)) {
      throw new IllegalArgumentException(
        s"Table ${table.identifier.table} is already cached.")
    }

    // Cache the table using the specified storage level
    val storageLevelObj = StorageLevel.fromString(storageLevel)
    sparkSession.catalog.cacheTable(table.identifier.table, storageLevelObj)

    // Return a single row indicating success
    Seq(Row(s"Table ${table.identifier.table} cached successfully with storage level $storageLevel"))
  }
}

