    val winners = fourConnect.winningSpots(activeChip)

    for {
      (spot,spotView) <- gameSpots
      winner <- winners
      spot <- winner
      if spot.col == spotView.getSpot.col && spot.row == spotView.getSpot.row
    } {
      if (gameStartedSubject.gameStarted) finishGame()
      spotView.blink()
    }
  }

