import org.apache.hadoop.fs.{FileSystem, Path}
import org.apache.gearpump.streaming.StateStore
import org.apache.gearpump.streaming.hdfs.HdfsUtils

class HadoopCheckpointStoreReader(
    val hadoopConf: org.apache.hadoop.conf.Configuration,
    val checkpointPath: String) extends Serializable {

  private val fs: FileSystem = HdfsUtils.getFileSystem(hadoopConf, checkpointPath)

  def readCheckpoint(): Option[StateStore] = {
    val checkpointFile = new Path(checkpointPath)
    if (!fs.exists(checkpointFile)) {
      None
    } else {
      try {
        val inputStream = fs.open(checkpointFile)
        val stateStore = StateStore.deserialize(inputStream)
        inputStream.close()
        Some(stateStore)
      } catch {
        case _: EOFException =>
          // If the checkpoint file is empty, treat it as no checkpoint
          None
        case _: Exception =>
          // Any other exception indicates a corrupted or unreadable checkpoint
          None
      }
    }
  }

  def close(): Unit = {
    if (fs != null) {
      fs.close()
    }
  }
}

