class DateColumnFilterSuite extends FunSuite with Matchers {
  test("date column filter: basic functionality") {
    val dateColumn = new DateColumn(1000)
    val date = java.sql.Date.valueOf("2023-01-01")
    val row = InternalRow.fromSeq(Seq(date))
    val filter = new DateColumnFilter(0, Literal(date), Expression.EQ)

    // Test equality
    filter.eval(row) shouldBe true

    // Test inequality
    val differentDate = java.sql.Date.valueOf("2023-01-02")
    val differentRow = InternalRow.fromSeq(Seq(differentDate))
