  private var jsonpEnabled: Boolean = false

  @BeanProperty
  def setJsonpCallback(jsonpCallback: String): Unit = {
    this.jsonpCallback = jsonpCallback
  }

  @BeanProperty
  def setJsonpEnabled(jsonpEnabled: Boolean): Unit = {
    this.jsonpEnabled = jsonpEnabled
  }

  override protected def renderMergedOutputModel(model: util.Map[String, AnyRef], request: HttpServletRequest, response: HttpServletResponse): Unit = {
    if (jsonpEnabled && jsonpCallback != null && jsonpCallback.nonEmpty) {
      response.setContentType("application/javascript")
      val jsonpObject = new JSONPObject(jsonpCallback, model)
      JsonUtils.writeValueAsString(jsonpObject, getJsonObjectMapper)
      val writer = response.getWriter
      writer.write(JsonUtils.writeValueAsString(jsonpObject, getJsonObjectMapper))
      writer.flush()
    } else {
      super.renderMergedOutputModel(model, request, response)
    }
  }
}

