trait Semiring[T] extends Serializable {
  def add(x: T, y: T): T
  def mul(x: T, y: T): T
  def zero: T
  def one: T

  // Default implementations for common operations
  def addAll(values: Iterable[T]): T = values.foldLeft(zero)(add)
  def mulAll(values: Iterable[T]): T = values.foldLeft(one)(mul)

  // Helper method to create an array of the given size filled with zeros
  def zeroArray(size: Int): Array[T] = Array.fill(size)(zero)
  def zeroArray2D(rows: Int, cols: Int): Array[Array[T]] = Array.fill(rows)(Array.fill(cols)(zero))

  // Default implementation using the zero element for sum and product
  def sum(values: Iterable[T]): T = addAll(values)
  def product(values: Iterable[T]): T = mulAll(values)

  // Identity element for addition and multiplication
  def isZero(x: T): Boolean = x == zero
  def isOne(x: T): Boolean = x == one
}

