object Presenter extends Presenter {
  def render: NodeSeq = {
    val content = <div id="presenter-content">Loading...</div>
    bind("presenter", content,
      "title" -> "Welcome to the Presenter",
      "content" -> <p>This is a dynamic presenter component using LiftWeb.</p>
    )
  }

  def updateContent(html: String): JsCmd = {
    SetHtml("presenter-content", Text(html))
  }

  override def doAfterRender: JsCmd = {
    // Initialize any client-side behavior after rendering
    if (isFirstRender) {
      val initCmd = Script(
        """console.log("Presenter component initialized");"""
      )
      initCmd
    } else {
      PassThru
    }
  }

  // Handle incoming messages from the client
  def receive: PartialFunction[Any, Unit] = {
    case UpdateContent(html) =>
      // Update the content via JavaScript command
      val cmd = updateContent(html)
      val _ = ajaxCommand(cmd)
  }
}

