private val viewStream = streamId(OfficeEventStream(officeInfo))

  override def receive: Receive = {
    case UpdateViewRequest(streamId, from, to) =>
      val query = ReadAllEventsForward(from, to, includeEvents = true, includeMetadata = false)
      esConn ! query

    case ReadAllEventsForwardSuccess(events) =>
      val processedEvents = events.collect {
        case EventReadSuccess(event) =>
          viewHandler.handle(event)
      }

      processedEvents.foreach {
        case Success(_) =>
        case Failure(t) =>
          log.error(t, "Failed to update view for event: {}", event.eventId)
      }

      sender() ! UpdateViewSuccess

    case ReadAllEventsForwardFailure(cause) =>
      log.error(cause, "Failed to read events for view update")
      sender() ! UpdateViewFailure(cause)

    case UpdateViewSuccess =>
      log.info("View updated successfully")

    case UpdateViewFailure(cause) =>
      log.error(cause, "View update failed")
  }
}

