private val viewStream = streamId(OfficeEventStream(officeInfo))

  override def receive: Receive = {
    case UpdateView(aggregateId, version, events) =>
      val update = viewHandler.handle(events)
      val streamId = viewStream
      val eventNumber = Exact(version)

      esConn ! AppendToStream(streamId, eventNumber, update.map(_.toEvent))

      context.become(waitingForAck(streamId, version, events, update, context.sender()))
  }

  private def waitingForAck(streamId: String, version: Long, events: Seq[Event], update: Seq[ViewEvent], replyTo: ActorRef): Receive = {
    case Status.Success(_) =>
      replyTo ! ViewUpdated(aggregateId, version)
      context.unbecome()

    case Failure(cause) =>
      log.error(cause, s"Failed to update view for stream $streamId at version $version")
      replyTo ! ViewUpdateFailed(aggregateId, version, cause.getMessage)
      context.unbecome()
  }
}

