private val viewStreamId = streamId(OfficeEventStream(officeInfo))

  override def receive: Receive = {
    case UpdateView =>
      esConn ! ReadStreamEventsForward(viewStreamId, 0, Long.MaxValue, true)
    case ReadStreamEventsSuccess(events) =>
      val updatedEvents = events
        .sortBy(_.event.eventNumber)
        .map { e =>
          viewHandler.handle(ReadEvent(e.event, e.event.eventNumber, e.event.eventType, e.event.data))
        }
      updatedEvents.foreach {
        case Success(_) =>
        case Failure(t) =>
          log.error(t, "Error updating view")
      }
      context.become(processing)
    case ReadStreamEventsFailure(cause) =>
      log.error(cause, "Failed to read events for view update")
      context.stop(self)
  }

  private val processing: Receive = {
    case UpdateView =>
      // Skip updates while processing
    case _ =>
      // Ignore other messages during processing
  }
}

