override def getAllMaterialDeterminationEvents(
      museumId: MuseumId,
      objectUUID: ObjectUUID
  ): FutureMusitResult[Seq[MaterialDetermination]] = {
    val action = (
      for {
        events <- conservationEventTable
          .filter(e => e.museumId === museumId && e.objectUUID === objectUUID)
          .filter(e => e.eventType === MaterialDetermination.eventType)
          .result
        enrichedEvents <- DBIO.sequence(events.map { e =>
          enrichWithSpecialAttributes(e.eventId, e)
        })
      } yield enrichedEvents.map(_.asInstanceOf[MaterialDetermination])
    ).transactionally

    daoUtils.dbRun(
      action,
      s"An unexpected error occurred fetching all MaterialDetermination events for object $objectUUID in museum $museumId"
    )
  }

