  private val interpreter = {
    val s = settings
    s.classpath.value = cp
    s.usejavacp.value = true
    s.embeddedDefaults(cl)
    new IMain(s)
  }

  private val completion = new JLineCompletion(interpreter)

  def evaluate(code: String): SimpleEvaluationObject = {
    val result = interpreter.interpret(code)
    result match {
      case Success => {
        val output = interpreter.valueOfTerm("result")
        new SimpleEvaluationObject(output, null)
      }
      case Error => {
        val error = interpreter.lastException.get
        new SimpleEvaluationObject(null, error.getMessage)
      }
    }
  }

  def getCompletion(text: String, cursor: Int): List[String] = {
    completion.complete(text, cursor) match {
      case Some(candidates) => candidates.candidates.toList
      case None => List.empty
    }
  }

  def reset(): Unit = {
    interpreter.reset()
  }

  def setClasspath(path: String): Unit = {
    cp = path
    settings.classpath.value = cp
    reset()
  }
}

