object PartitionUtils {

  /**
   * Re-partitions a DataFrame based on a specified column and number of partitions.
   *
   * @param df The input DataFrame to repartition
   * @param partitionColumn The column to partition by
   * @param numPartitions The number of partitions to create
   * @return A new DataFrame repartitioned by the specified column and number of partitions
   */
  def repartitionByColumn(df: DataFrame, partitionColumn: String, numPartitions: Int): DataFrame = {
    if (df.columns.contains(partitionColumn)) {
      df.repartition(numPartitions, col(partitionColumn))
    } else {
      throw new IllegalArgumentException(s"Column $partitionColumn does not exist in the DataFrame")
    }
  }

