object PartitionUtils {

  /**
   * Re-partitions a DataFrame to a specified number of partitions while preserving data distribution.
   *
   * @param df The input DataFrame to be re-partitioned
   * @param numPartitions The desired number of partitions
   * @param spark The SparkSession instance
   * @return A new DataFrame re-partitioned to the specified number of partitions
   */
  def repartitionDataFrame(df: DataFrame, numPartitions: Int)(implicit spark: SparkSession): DataFrame = {
    if (numPartitions <= 0) {
      throw new IllegalArgumentException("Number of partitions must be greater than zero.")
    }
    if (df.rdd.getNumPartitions == numPartitions) {
      return df
    }

    df.repartition(numPartitions)
  }

